  "about.consumption_madurai_title":  { en: "Default consumption assumptions (Madurai)", ta: "இயல்பான நுகர்வு அனுமானங்கள் (மதுரை)" , kn: "ಪೂರ್ವನಿಯೋಜಿತ ಬಳಕೆ ಊಹೆಗಳು (ಮಧುರೈ)"},
  "about.consumption_intro":          { en: "Madurai-specific defaults used to compute days-of-water-left. These are conservative starting points; the dashboard exposes sliders so users can substitute their own.", ta: "மதுரைக்கு தனிப்பட்ட இயல்புநிலைகள் மீதமுள்ள நீர் நாட்களை கணக்கிட பயன்படுத்தப்படுகின்றன. இவை பழமைவாத தொடக்கப் புள்ளிகள்; பயனர்கள் தங்கள் சொந்த மதிப்புகளை மாற்ற டாஷ்போர்டில் ஸ்லைடர்கள் வழங்கப்படுகின்றன." , kn: "ಉಳಿದ-ನೀರಿನ-ದಿನಗಳನ್ನು ಲೆಕ್ಕಹಾಕಲು ಮಧುರೈಗೆ ನಿರ್ದಿಷ್ಟ ಪೂರ್ವನಿಯೋಜಿತಗಳನ್ನು ಬಳಸಲಾಗಿದೆ. ಇವು ಸಂಪ್ರದಾಯವಾದಿ ಪ್ರಾರಂಭ ಬಿಂದುಗಳು; ಡ್ಯಾಶ್‌ಬೋರ್ಡ್ ಸ್ಲೈಡರ್‌ಗಳನ್ನು ತೋರಿಸುತ್ತದೆ ಆದ್ದರಿಂದ ಬಳಕೆದಾರರು ತಮ್ಮದೇ ಆದ ಮೌಲ್ಯಗಳನ್ನು ಬದಲಿಸಬಹುದು."},
  "about.col_parameter": { en: "Parameter", ta: "அளவுரு", kn: "ಮಾನದಂಡ" },
  "about.col_default": { en: "Default", ta: "இயல்புநிலை", kn: "ಪೂರ್ವನಿಯೋಜಿತ" },
  "about.col_source": { en: "Source / note", ta: "ஆதாரம் / குறிப்பு", kn: "ಮೂಲ / ಟಿಪ್ಪಣಿ" },
  "about.row_demand": { en: "Daily city demand", ta: "தினசரி நகர தேவை", kn: "ದೈನಂದಿನ ನಗರ ಬೇಡಿಕೆ" },
  "about.row_demand_note":            { en: "Madurai Corporation operational estimate; ~85 MLD piped supply across 100 wards.", ta: "மதுரை மாநகராட்சி செயல்பாட்டு மதிப்பீடு; 100 வார்டுகளில் ~85 MLD குழாய் வழங்கல்." , kn: "ಮಧುರೈ ಮಹಾನಗರಪಾಲಿಕೆ ಕಾರ್ಯಾಚರಣಾ ಅಂದಾಜು; 100 ವಾರ್ಡ್‌ಗಳಲ್ಲಿ ~85 MLD ಪೈಪ್ಡ್ ಪೂರೈಕೆ."},
  "about.row_desal": { en: "Desalination contribution", ta: "உப்புநீக்கம் பங்களிப்பு", kn: "ಡಿಸ್ಯಾಲ್ ಕೊಡುಗೆ" },
  "about.row_desal_note":             { en: "No desal plants commissioned for Madurai.", ta: "மதுரைக்கு உப்புநீக்க நிலையங்கள் எதுவும் இயக்கப்படவில்லை." , kn: "ಮಧುರೈಗೆ ಯಾವುದೇ ಡಿಸ್ಯಾಲ್ ಸ್ಥಾವರಗಳನ್ನು ಚಾಲನೆ ಮಾಡಲಾಗಿಲ್ಲ."},
  "about.row_gw": { en: "Groundwater contribution", ta: "நிலத்தடி நீர் பங்களிப்பு", kn: "ಅಂತರ್ಜಲ ಕೊಡುಗೆ" },
  "about.row_gw_value": { en: "Excluded from days-left", ta: "மீதமுள்ள நாட்களிலிருந்து விலக்கப்பட்டது", kn: "ಉಳಿದ ದಿನಗಳಿಂದ ಹೊರಗಿಡಲಾಗಿದೆ" },
  "about.row_gw_note":                { en: "Borewells supplement the piped supply but exact MLD is unmodelled. CGWB block + ward-level depth views show groundwater stress separately.", ta: "ஆழ்துளைக் கிணறுகள் குழாய் வழங்கலை நிரப்புகின்றன ஆனால் சரியான MLD மாதிரியாக்கப்படவில்லை. CGWB தொகுதி + வார்டு-நிலை ஆழக் காட்சிகள் நிலத்தடி நீர் அழுத்தத்தைத் தனியாகக் காட்டுகின்றன." , kn: "ಬೋರ್‌ವೆಲ್‌ಗಳು ಪೈಪ್ಡ್ ಪೂರೈಕೆಯನ್ನು ಪೂರಕಗೊಳಿಸುತ್ತವೆ ಆದರೆ ನಿಖರವಾದ MLD ಮಾಡೆಲ್ ಮಾಡಲಾಗಿಲ್ಲ. CGWB ಬ್ಲಾಕ್ + ವಾರ್ಡ್-ಮಟ್ಟದ ಆಳ ನೋಟಗಳು ಅಂತರ್ಜಲ ಒತ್ತಡವನ್ನು ಪ್ರತ್ಯೇಕವಾಗಿ ತೋರಿಸುತ್ತವೆ."},
  "about.row_evap": { en: "Reservoir evaporation", ta: "நீர்த்தேக்க ஆவியாதல்", kn: "ಜಲಾಶಯ ಆವಿಯಾಗುವಿಕೆ" },
  "about.row_evap_value": { en: "Not modelled", ta: "மாதிரியாக்கப்படவில்லை", kn: "ಮಾಡೆಲ್ ಮಾಡಲಾಗಿಲ್ಲ" },
  "about.row_evap_note":              { en: "Vaigai / Mullaperiyar evaporation is non-trivial in summer; planned for v2 once a daily ET0 series is wired.", ta: "வைகை / முல்லைப் பெரியார் ஆவியாதல் கோடையில் அதிகமாக உள்ளது; தினசரி ET0 தொடர் இணைக்கப்பட்டவுடன் v2-க்காக திட்டமிடப்பட்டுள்ளது." , kn: "ವೈಗೈ / ಮುಲ್ಲೈಪೆರಿಯಾರ್ ಆವಿಯಾಗುವಿಕೆ ಬೇಸಿಗೆಯಲ್ಲಿ ಹೆಚ್ಚು; ದೈನಂದಿನ ET0 ಸರಣಿ ಬಂದ ನಂತರ v2 ಗೆ ಯೋಜಿಸಲಾಗಿದೆ."},

