  "hero.same_day_comparison": { en: "On this day in {year}:", ta: "{year}-ல் இந்த நாளில்:", kn: "{year} ರ ಇದೇ ದಿನ:" },
  "hero.around_day_comparison": { en: "Around this day in {year}:", ta: "{year}-ல் இந்நாள் அளவில்:", kn: "{year} ರ ಸುಮಾರು ಇದೇ ದಿನ:" },
  "hero.better_today": { en: "(better today)",            ta: "(இன்று சிறப்பாக)", kn: "(ಇಂದು ಉತ್ತಮ)" },
