  "wb.lost": { en: "documented lost or encroached",          ta: "ஆவணப்படுத்தப்பட்ட இழந்த அல்லது ஆக்கிரமிக்கப்பட்டவை", kn: "ದಾಖಲಿತ ಕಳೆದು ಹೋದ ಅಥವಾ ಒತ್ತುವರಿಯಾದ" },
