  "wb_panel.capacity_vs_encroach": { en: "Note: Storage capacity was not revised to reflect encroachment in the census data.", ta: "குறிப்பு: கணக்கெடுப்பு தரவில் ஆக்கிரமிப்பை பிரதிபலிக்கும் வகையில் சேமிப்பு திறன் மாற்றப்படவில்லை.", kn: "ಗಮನಿಸಿ: ಒತ್ತುವರಿಯನ್ನು ಪ್ರತಿಬಿಂಬಿಸಲು ಜನಗಣತಿ ದತ್ತಾಂಶದಲ್ಲಿ ಸಂಗ್ರಹ ಸಾಮರ್ಥ್ಯವನ್ನು ಪರಿಷ್ಕರಿಸಲಾಗಿಲ್ಲ." },
  "wb_panel.capacity_hidden_suspect": { en: "Storage capacity is hidden for this record because the census values appear internally inconsistent with the recorded area, depth, or current-use status.", ta: "இந்த பதிவிற்கான சேமிப்பு திறன் மறைக்கப்பட்டுள்ளது; காரணம், கணக்கெடுப்பில் உள்ள திறன் மதிப்புகள் பதிவுசெய்யப்பட்ட பரப்பளவு, ஆழம் அல்லது தற்போதைய பயன்பாட்டு நிலையுடன் உள்ளகமாக பொருந்தவில்லை.", kn: "ಜನಗಣತಿ ಮೌಲ್ಯಗಳು ದಾಖಲಿತ ಪ್ರದೇಶ, ಆಳ ಅಥವಾ ಪ್ರಸ್ತುತ-ಬಳಕೆ ಸ್ಥಿತಿಯೊಂದಿಗೆ ಅಸಂಗತವಾಗಿರುವುದರಿಂದ ಈ ದಾಖಲೆಗೆ ಸಂಗ್ರಹ ಸಾಮರ್ಥ್ಯವನ್ನು ಮರೆಮಾಡಲಾಗಿದೆ." },
  "wb_panel.capacity_units_note": { en: "Government census capacity values are reported in cubic meters (m3).", ta: "அரசு கணக்கெடுப்பில் சேமிப்பு திறன் மதிப்புகள் கன மீட்டரில் (m3) வழங்கப்படுகின்றன.", kn: "ಸರ್ಕಾರಿ ಜನಗಣತಿ ಸಾಮರ್ಥ್ಯ ಮೌಲ್ಯಗಳನ್ನು ಘನ ಮೀಟರ್‌ಗಳಲ್ಲಿ (m3) ವರದಿ ಮಾಡಲಾಗಿದೆ." },
  "wb_panel.census_source_label": { en: "First Census of Water Bodies (2018-19), Govt. of India", ta: "நீர்நிலைகளின் முதல் கணக்கெடுப்பு (2018-19), இந்திய அரசு", kn: "ಜಲಮೂಲಗಳ ಮೊದಲ ಜನಗಣತಿ (2018-19), ಭಾರತ ಸರ್ಕಾರ" },
  "wb_panel.satellite_context": { en: "Satellite Context",     ta: "செயற்கைக்கோள் நிலை", kn: "ಉಪಗ್ರಹ ಸಂದರ್ಭ" },
  "wb_panel.satellite_persistence_year_round": { en: "Usually retains water year-round.", ta: "பொதுவாக ஆண்டு முழுவதும் நீரை தக்கவைக்கிறது.", kn: "ಸಾಮಾನ್ಯವಾಗಿ ವರ್ಷಪೂರ್ತಿ ನೀರನ್ನು ಉಳಿಸಿಕೊಳ್ಳುತ್ತದೆ." },
  "wb_panel.satellite_persistence_most_year": { en: "Usually holds water through most of the year.", ta: "பொதுவாக ஆண்டின் பெரும்பகுதியில் நீரை தக்கவைக்கிறது.", kn: "ಸಾಮಾನ್ಯವಾಗಿ ವರ್ಷದ ಹೆಚ್ಚಿನ ಭಾಗ ನೀರನ್ನು ಹಿಡಿದಿಡುತ್ತದೆ." },
  "wb_panel.satellite_persistence_seasonal": { en: "Usually holds water seasonally, with some drier months.", ta: "பொதுவாக பருவகாலமாக நீரை தக்கவைக்கிறது; சில மாதங்கள் வறண்டதாக இருக்கும்.", kn: "ಸಾಮಾನ್ಯವಾಗಿ ಋತುಮಾನವಾಗಿ ನೀರನ್ನು ಹಿಡಿದಿಡುತ್ತದೆ, ಕೆಲವು ಒಣ ತಿಂಗಳುಗಳೊಂದಿಗೆ." },
  "wb_panel.satellite_persistence_wet_months": { en: "Usually holds water mainly in wetter months.", ta: "பொதுவாக அதிக மழைபெறும் மாதங்களில் மட்டுமே நீரை தக்கவைக்கிறது.", kn: "ಸಾಮಾನ್ಯವಾಗಿ ಮುಖ್ಯವಾಗಿ ಒದ್ದೆಯ ತಿಂಗಳುಗಳಲ್ಲಿ ನೀರನ್ನು ಹಿಡಿದಿಡುತ್ತದೆ." },
  "wb_panel.satellite_persistence_ephemeral": { en: "Usually appears dry for much of the year.", ta: "பொதுவாக ஆண்டின் பெரும்பகுதியில் வறண்டதாக தோன்றுகிறது.", kn: "ಸಾಮಾನ್ಯವಾಗಿ ವರ್ಷದ ಹೆಚ್ಚಿನ ಭಾಗ ಒಣಗಿರುತ್ತದೆ." },
  "wb_panel.satellite_summary_lower": { en: "Recent visible spread is about {observed} versus a usual seasonal footprint of {baseline} ({delta} below usual).", ta: "சமீபத்திய காணக்கூடிய நீர்ப்பரப்பு சுமார் {observed}; இந்த பருவத்தில் வழக்கமான {baseline} பரப்புடன் ஒப்பிடும்போது {delta} குறைவாக உள்ளது.", kn: "ಇತ್ತೀಚಿನ ಗೋಚರ ಹರಡುವಿಕೆ ಸುಮಾರು {observed}, ಸಾಮಾನ್ಯ ಋತುಮಾನ ಗಾತ್ರವಾದ {baseline} ಗೆ ಹೋಲಿಸಿದರೆ ({delta} ಸಾಮಾನ್ಯಕ್ಕಿಂತ ಕಡಿಮೆ)." },
  "wb_panel.satellite_summary_near_normal": { en: "Recent visible spread is about {observed}, close to the usual seasonal footprint of {baseline}.", ta: "சமீபத்திய காணக்கூடிய நீர்ப்பரப்பு சுமார் {observed}; இந்த பருவத்தின் வழக்கமான {baseline} பரப்பிற்கு அருகில் உள்ளது.", kn: "ಇತ್ತೀಚಿನ ಗೋಚರ ಹರಡುವಿಕೆ ಸುಮಾರು {observed}, ಸಾಮಾನ್ಯ ಋತುಮಾನ ಗಾತ್ರವಾದ {baseline} ಗೆ ಸಮೀಪ." },
  "wb_panel.satellite_summary_higher": { en: "Recent visible spread is about {observed} versus a usual seasonal footprint of {baseline} ({delta} above usual).", ta: "சமீபத்திய காணக்கூடிய நீர்ப்பரப்பு சுமார் {observed}; இந்த பருவத்தின் வழக்கமான {baseline} பரப்புடன் ஒப்பிடும்போது {delta} அதிகமாக உள்ளது.", kn: "ಇತ್ತೀಚಿನ ಗೋಚರ ಹರಡುವಿಕೆ ಸುಮಾರು {observed}, ಸಾಮಾನ್ಯ ಋತುಮಾನ ಗಾತ್ರವಾದ {baseline} ಗೆ ಹೋಲಿಸಿದರೆ ({delta} ಸಾಮಾನ್ಯಕ್ಕಿಂತ ಹೆಚ್ಚು)." },
  "wb_panel.satellite_metric_current": { en: "Recent visible spread", ta: "சமீபத்திய காணக்கூடிய பரப்பு", kn: "ಇತ್ತೀಚಿನ ಗೋಚರ ಹರಡುವಿಕೆ" },
