  "dash.catchment_headline_below": { en: "{count} of {total} supply reservoir catchments are below normal over {windowDays} days.", ta: "{windowDays} நாட்களில் {total} குடிநீர் நீர்த்தேக்க நீர்ப்பிடிப்பு பகுதிகளில் {count} சாதாரணத்திற்குக் கீழே உள்ளன.", kn: "{total} ಪೂರೈಕೆ ಜಲಾಶಯ ಜಲಾನಯನಗಳಲ್ಲಿ {count} ಕಳೆದ {windowDays} ದಿನಗಳಲ್ಲಿ ಸಾಮಾನ್ಯಕ್ಕಿಂತ ಕಡಿಮೆ." },
  "dash.catchment_headline_above": { en: "{count} of {total} supply reservoir catchments are above normal over {windowDays} days.", ta: "{windowDays} நாட்களில் {total} குடிநீர் நீர்த்தேக்க நீர்ப்பிடிப்பு பகுதிகளில் {count} சாதாரணத்தை விட மேலாக உள்ளன.", kn: "{total} ಪೂರೈಕೆ ಜಲಾಶಯ ಜಲಾನಯನಗಳಲ್ಲಿ {count} ಕಳೆದ {windowDays} ದಿನಗಳಲ್ಲಿ ಸಾಮಾನ್ಯಕ್ಕಿಂತ ಹೆಚ್ಚು." },
  "dash.catchment_headline_near_normal": { en: "Most supply reservoir catchments are near normal over {windowDays} days.", ta: "{windowDays} நாட்களில் பெரும்பாலான குடிநீர் நீர்த்தேக்க நீர்ப்பிடிப்பு பகுதிகள் சாதாரண நிலைக்கு அருகில் உள்ளன.", kn: "ಹೆಚ್ಚಿನ ಪೂರೈಕೆ ಜಲಾಶಯ ಜಲಾನಯನಗಳು ಕಳೆದ {windowDays} ದಿನಗಳಲ್ಲಿ ಸಾಮಾನ್ಯಕ್ಕೆ ಸಮೀಪ." },
  "dash.catchment_headline_mixed": { en: "Catchment rainfall is mixed across Chennai's supply reservoirs over {windowDays} days.", ta: "{windowDays} நாட்களில் சென்னையின் குடிநீர் நீர்த்தேக்க நீர்ப்பிடிப்பு பகுதிகளில் மழை நிலை கலவையாக உள்ளது.", kn: "ಚೆನ್ನೈನ ಪೂರೈಕೆ ಜಲಾಶಯಗಳಾದ್ಯಂತ ಜಲಾನಯನ ಮಳೆ ಕಳೆದ {windowDays} ದಿನಗಳಲ್ಲಿ ಮಿಶ್ರಿತ." },
  "dash.catchment_detail_below": { en: "{reservoir} catchment is {anomalyPct}% below its {windowDays}-day norm.", ta: "{reservoir} நீர்ப்பிடிப்பு பகுதி தனது {windowDays} நாள் இயல்பை விட {anomalyPct}% குறைவாக உள்ளது.", kn: "{reservoir} ಜಲಾನಯನವು ತನ್ನ {windowDays}-ದಿನ ಸಾಮಾನ್ಯಕ್ಕಿಂತ {anomalyPct}% ಕಡಿಮೆ." },
  "dash.catchment_detail_above": { en: "{reservoir} catchment is {anomalyPct}% above its {windowDays}-day norm.", ta: "{reservoir} நீர்ப்பிடிப்பு பகுதி தனது {windowDays} நாள் இயல்பை விட {anomalyPct}% அதிகமாக உள்ளது.", kn: "{reservoir} ಜಲಾನಯನವು ತನ್ನ {windowDays}-ದಿನ ಸಾಮಾನ್ಯಕ್ಕಿಂತ {anomalyPct}% ಹೆಚ್ಚು." },
  "dash.catchment_detail_near_normal": { en: "Most monitored catchments are close to their usual seasonal rainfall.", ta: "கண்காணிக்கப்பட்ட பெரும்பாலான நீர்ப்பிடிப்பு பகுதிகள் தங்களின் வழக்கமான பருவமழை நிலைக்கு அருகில் உள்ளன.", kn: "ಹೆಚ್ಚಿನ ಗಮನಿಸಲಾದ ಜಲಾನಯನಗಳು ತಮ್ಮ ಸಾಮಾನ್ಯ ಋತುಮಾನದ ಮಳೆಗೆ ಸಮೀಪ." },
  "dash.catchment_label_well_below": { en: "Well below", ta: "மிகக் குறைவு", kn: "ತುಂಬಾ ಕೆಳಗೆ" },
