  // Taglines
  "flood.tagline_hazard": { en: "Lost water bodies and concretized floodplains increase hazard in these zones", ta: "இழக்கப்பட்ட நீர்நிலைகள் மற்றும் கான்கிரீட் மயமான வெள்ளச்சமவெளிகள் இந்த மண்டலங்களில் ஆபத்தை அதிகரிக்கின்றன", kn: "ಕಳೆದು ಹೋದ ಜಲಮೂಲಗಳು ಮತ್ತು ಕಾಂಕ್ರೀಟ್ ಮಾಡಲಾದ ಪ್ರವಾಹ ಮೈದಾನಗಳು ಈ ವಲಯಗಳಲ್ಲಿ ಅಪಾಯ ಹೆಚ್ಚಿಸುತ್ತವೆ" },
  "flood.tagline_historical": { en: "Same areas flooded in both events - the underlying vulnerabilities persist", ta: "இரண்டு நிகழ்வுகளிலும் அதே பகுதிகள் வெள்ளத்தில் மூழ்கின - அடிப்படை பாதிப்புகள் நீடிக்கின்றன", kn: "ಎರಡೂ ಘಟನೆಗಳಲ್ಲಿ ಅದೇ ಪ್ರದೇಶಗಳು ಪ್ರವಾಹಕ್ಕೆ ಒಳಗಾದವು - ಆಧಾರ ದುರ್ಬಲತೆಗಳು ಮುಂದುವರಿಯುತ್ತಿವೆ" },
  "flood.tagline_drainage": { en: "Where drains are absent or degraded, waterlogging blocks groundwater recharge", ta: "வடிகால்கள் இல்லாத அல்லது சீரழிந்த இடங்களில், நீர் தேக்கம் நிலத்தடி நீர் நிரப்புதலைத் தடுக்கிறது", kn: "ಚರಂಡಿಗಳು ಇಲ್ಲದ ಅಥವಾ ಹಾಳಾದ ಸ್ಥಳಗಳಲ್ಲಿ, ನೀರಿನ ಸಂಗ್ರಹ ಅಂತರ್ಜಲ ಮರುಪೂರಣವನ್ನು ತಡೆಯುತ್ತದೆ" },

