  "report.fact_pumping": { en: "Sewage pumping",                    ta: "கழிவுநீர் பம்பிங்", kn: "ಚರಂಡಿ ಪಂಪಿಂಗ್" },
  "report.fact_industrial": { en: "Industrial zones",                  ta: "தொழிற்சாலை மண்டலங்கள்", kn: "ಕೈಗಾರಿಕಾ ವಲಯಗಳು" },
  "report.fact_water_body_names": { en: "Key water bodies",                  ta: "முக்கிய நீர்நிலைகள்", kn: "ಪ್ರಮುಖ ಜಲಮೂಲಗಳು" },
  "report.none": { en: "None",                              ta: "இல்லை", kn: "ಯಾವುದೂ ಇಲ್ಲ" },
