  "uplift.no_improvement": { en: "No further improvement possible with remaining budget.", ta: "மீதமுள்ள பட்ஜெட்டில் மேலும் மேம்பாடு சாத்தியமில்லை.", kn: "ಉಳಿದ ಬಜೆಟ್‌ನಿಂದ ಹೆಚ್ಚಿನ ಸುಧಾರಣೆ ಸಾಧ್ಯವಿಲ್ಲ." },
  "uplift.no_allocations": { en: "No allocations needed - budget is zero or ward is already top-ranked.", ta: "ஒதுக்கீடுகள் தேவையில்லை - பட்ஜெட் பூஜ்ஜியம் அல்லது வார்டு ஏற்கனவே உயர் தரத்தில் உள்ளது.", kn: "ಹಂಚಿಕೆಗಳು ಬೇಕಿಲ್ಲ - ಬಜೆಟ್ ಶೂನ್ಯ ಅಥವಾ ವಾರ್ಡ್ ಈಗಾಗಲೇ ಮೇಲ್ಮಟ್ಟದಲ್ಲಿದೆ." },
  "uplift.cost_range": { en: "INR {low}-{high} Cr", ta: "INR {low}-{high} கோடி", kn: "INR {low}-{high} ಕೋಟಿ" },
  "uplift.disclaimer": { en: "Hypothetical estimates based on published government project costs. Budget allocation uses a greedy heuristic - recommendations are approximate, not globally optimal. Actual costs vary by site conditions, land availability, and procurement method. Not a tender or budget proposal.", ta: "வெளியிடப்பட்ட அரசு திட்ட செலவுகளின் அடிப்படையிலான கற்பனையான மதிப்பீடுகள். பட்ஜெட் ஒதுக்கீடு ஒரு தோராயமான வழிமுறையைப் பயன்படுத்துகிறது - பரிந்துரைகள் தோராயமானவை. உண்மையான செலவுகள் தள நிலைமைகள், நில கிடைக்கும் தன்மை மற்றும் கொள்முதல் முறையால் மாறுபடும்.", kn: "ಪ್ರಕಟಿತ ಸರ್ಕಾರಿ ಯೋಜನಾ ವೆಚ್ಚಗಳ ಆಧಾರದ ಮೇಲೆ ಊಹಾತ್ಮಕ ಅಂದಾಜುಗಳು. ಬಜೆಟ್ ಹಂಚಿಕೆ ಲೋಭ ಹ್ಯೂರಿಸ್ಟಿಕ್ ಬಳಸುತ್ತದೆ - ಶಿಫಾರಸುಗಳು ಸ್ಥೂಲ, ಜಾಗತಿಕವಾಗಿ ಸೂಕ್ತವಲ್ಲ. ಸ್ಥಳ ಸ್ಥಿತಿ ಮತ್ತು ಸಂಗ್ರಹಣಾ ವಿಧಾನದ ಮೇಲೆ ವಾಸ್ತವ ವೆಚ್ಚಗಳು ಬದಲಾಗುತ್ತವೆ. ಟೆಂಡರ್ ಅಥವಾ ಬಜೆಟ್ ಪ್ರಸ್ತಾಪವಲ್ಲ." },

  // Intervention names
  "uplift.int_build_drain": { en: "Build storm drains", ta: "புயல் வடிகால் கட்டுதல்", kn: "ಮಳೆನೀರು ಚರಂಡಿಗಳನ್ನು ನಿರ್ಮಿಸಿ" },
  "uplift.int_build_drain_desc": { en: "New lined stormwater drains to increase drainage coverage.", ta: "வடிகால் கவரேஜை அதிகரிக்க புதிய வரிசைப்படுத்தப்பட்ட புயல்நீர் வடிகால்கள்.", kn: "ಒಳಚರಂಡಿ ವ್ಯಾಪ್ತಿಯನ್ನು ಹೆಚ್ಚಿಸಲು ಹೊಸ ಲೈನ್ ಮಾಡಿದ ಮಳೆನೀರು ಚರಂಡಿಗಳು." },
  "uplift.int_build_pumping_main": { en: "Extend sewage network", ta: "கழிவுநீர் நெட்வொர்க்கை நீட்டித்தல்", kn: "ಚರಂಡಿ ಜಾಲವನ್ನು ವಿಸ್ತರಿಸಿ" },
  "uplift.int_build_pumping_main_desc": { en: "New pumping mains to expand sewerage coverage.", ta: "கழிவுநீர் கவரேஜை விரிவுபடுத்த புதிய பம்பிங் குழாய்கள்.", kn: "ಚರಂಡಿ ವ್ಯಾಪ್ತಿಯನ್ನು ವಿಸ್ತರಿಸಲು ಹೊಸ ಪಂಪಿಂಗ್ ಮುಖ್ಯಗಳು." },
  "uplift.int_flood_mitigation": { en: "Flood zone mitigation", ta: "வெள்ள மண்டல தணிப்பு", kn: "ಪ್ರವಾಹ ವಲಯ ತಗ್ಗಿಸುವಿಕೆ" },
  "uplift.int_flood_mitigation_desc": { en: "Retention ponds, bund upgrades, and stormwater pump stations to reduce severe flood zones.", ta: "கடுமையான வெள்ள மண்டலங்களைக் குறைக்க தடுப்பு குளங்கள், கரை மேம்பாடுகள் மற்றும் மழைநீர் பம்ப் நிலையங்கள்.", kn: "ತೀವ್ರ ಪ್ರವಾಹ ವಲಯಗಳನ್ನು ಕಡಿಮೆ ಮಾಡಲು ಜಲ ಸಂಗ್ರಹಗಳು, ಬಂಡ್ ಸುಧಾರಣೆಗಳು ಮತ್ತು ಮಳೆನೀರು ಪಂಪ್ ಸ್ಟೇಷನ್‌ಗಳು." },
  "uplift.int_restore_wb": { en: "Restore water bodies", ta: "நீர்நிலைகளை மறுசீரமைத்தல்", kn: "ಜಲಮೂಲಗಳನ್ನು ಪುನರ್ನಿರ್ಮಿಸಿ" },
  "uplift.int_restore_wb_desc": { en: "Desilting, bund repair, and pollution control for degraded water bodies.", ta: "சீரழிந்த நீர்நிலைகளுக்கு தூர்வாரல் மற்றும் கரையோர பழுதுபார்ப்பு.", kn: "ಹಾಳಾದ ಜಲಮೂಲಗಳಿಗೆ ಡಿಸಿಲ್ಟಿಂಗ್, ಬಂಡ್ ದುರಸ್ತಿ ಮತ್ತು ಮಾಲಿನ್ಯ ನಿಯಂತ್ರಣ." },
  "uplift.int_revive_wb": { en: "Revive lost water bodies", ta: "இழக்கப்பட்ட நீர்நிலைகளை புதுப்பித்தல்", kn: "ಕಳೆದ ಜಲಮೂಲಗಳನ್ನು ಪುನರುಜ್ಜೀವಗೊಳಿಸಿ" },
  "uplift.int_revive_wb_desc": { en: "Reclaim and restore water bodies lost to encroachment.", ta: "ஆக்கிரமிப்பால் இழக்கப்பட்ட நீர்நிலைகளை மீட்டெடுத்தல்.", kn: "ಒತ್ತುವರಿಯಾಗಿ ಕಳೆದ ಜಲಮೂಲಗಳನ್ನು ಮರಳಿ ಪಡೆದು ಪುನರ್ನಿರ್ಮಿಸಿ." },

