  // ── Water Facts page (city name interpolated via {city}) ─────────────────
  "facts.page_title": { en: "{city} Water Facts", ta: "{city} நீர் உண்மைகள்", kn: "{city} ನೀರಿನ ಸತ್ಯಗಳು" },
  "facts.page_intro":       {
    en: "{city}'s water state in quotable numbers. Every fact has a source, a date, and a methodology link. Organised by freshness: today's live data, this year's government releases, historical milestones, and structural infrastructure.",
    ta: "{city}யின் நீர் நிலை மேற்கோள் எண்களில். ஒவ்வொரு உண்மைக்கும் ஒரு மூலம், தேதி மற்றும் முறைமை இணைப்பு உள்ளது. புதுமையின் அடிப்படையில் ஒழுங்கமைக்கப்பட்டது: இன்றைய நேரடித் தரவு, இந்த ஆண்டின் அரசாங்க வெளியீடுகள், வரலாற்று மைல்கற்கள், மற்றும் கட்டமைப்பு உள்கட்டமைப்பு.",
    kn: "{city} ನ ನೀರಿನ ಸ್ಥಿತಿ ಉಲ್ಲೇಖಿಸಬಹುದಾದ ಸಂಖ್ಯೆಗಳಲ್ಲಿ. ಪ್ರತಿ ಸತ್ಯಕ್ಕೂ ಮೂಲ, ದಿನಾಂಕ ಮತ್ತು ವಿಧಾನ ಲಿಂಕ್ ಇದೆ. ತಾಜಾತನದಿಂದ ಜೋಡಿಸಲಾಗಿದೆ: ಇಂದಿನ ನೇರ ದತ್ತಾಂಶ, ಈ ವರ್ಷದ ಸರ್ಕಾರಿ ಬಿಡುಗಡೆಗಳು, ಐತಿಹಾಸಿಕ ಮೈಲಿಗಲ್ಲುಗಳು ಮತ್ತು ಕಟ್ಟಡ ಮೂಲಸೌಕರ್ಯ.",
  },
  "facts.last_updated": { en: "Last updated", ta: "கடைசியாக புதுப்பிக்கப்பட்டது", kn: "ಕೊನೆಯದಾಗಿ ನವೀಕರಿಸಲಾಗಿದೆ" },
  "facts.as_of": { en: "As of", ta: "அன்று", kn: "ಪ್ರಕಾರ" },
  "facts.copy_quote": { en: "Copy quote", ta: "மேற்கோள் நகலெடு", kn: "ಉಲ್ಲೇಖ ನಕಲಿಸಿ" },
  "facts.copy_link": { en: "Copy link", ta: "இணைப்பை நகலெடு", kn: "ಲಿಂಕ್ ನಕಲಿಸಿ" },
  "facts.tweet": { en: "Tweet", ta: "ட்வீட்", kn: "ಟ್ವೀಟ್" },
  "facts.copied": { en: "Copied!", ta: "நகலெடுக்கப்பட்டது!", kn: "ನಕಲಿಸಲಾಗಿದೆ!" },
  "facts.card_anchor": { en: "Permalink to this fact", ta: "இந்த உண்மைக்கான நிரந்தர இணைப்பு", kn: "ಈ ಸತ್ಯಕ್ಕೆ ಪರ್ಮಾಲಿಂಕ್" },
  "facts.methodology_title": { en: "Methodology & sources", ta: "முறைமை & மூலங்கள்", kn: "ವಿಧಾನ ಮತ್ತು ಮೂಲಗಳು" },
  "facts.methodology_intro":{
    en: "Every number on this page is sourced from a publicly available dataset or official release. Live figures are refreshed daily from government monitoring feeds; annual figures show their vintage year; historical and structural figures are reference data with dated provenance.",
    ta: "இந்த பக்கத்தில் உள்ள ஒவ்வொரு எண்ணும் பொதுவில் கிடைக்கும் தரவுத்தொகுப்பு அல்லது அதிகாரப்பூர்வ வெளியீட்டிலிருந்து பெறப்பட்டது. நேரடி புள்ளிவிவரங்கள் தினசரி அரசு கண்காணிப்பு ஊட்டங்களிலிருந்து புதுப்பிக்கப்படுகின்றன.",
    kn: "ಈ ಪುಟದ ಪ್ರತಿ ಸಂಖ್ಯೆಯೂ ಸಾರ್ವಜನಿಕವಾಗಿ ಲಭ್ಯವಿರುವ ದತ್ತಾಂಶ ಅಥವಾ ಅಧಿಕೃತ ಬಿಡುಗಡೆಯಿಂದ ಬಂದಿದೆ. ನೇರ ಸಂಖ್ಯೆಗಳು ದಿನಂಪ್ರತಿ ರಿಫ್ರೆಶ್ ಆಗುತ್ತವೆ; ವಾರ್ಷಿಕ ಸಂಖ್ಯೆಗಳು ತಮ್ಮ ಆವೃತ್ತಿ ವರ್ಷವನ್ನು ತೋರಿಸುತ್ತವೆ; ಐತಿಹಾಸಿಕ ಮತ್ತು ಕಟ್ಟಡ ಸಂಖ್ಯೆಗಳು ದಿನಾಂಕದ ಮೂಲದೊಂದಿಗೆ ಉಲ್ಲೇಖ ದತ್ತಾಂಶ."
  },
  "facts.methodology_link": { en: "See full data sources →", ta: "முழு தரவு மூலங்களைப் பார்க்கவும் →", kn: "ಸಂಪೂರ್ಣ ದತ್ತಾಂಶ ಮೂಲಗಳನ್ನು ನೋಡಿ →" },

